function add(type,extra={}){checkpoint();const parent=chosen()?.type==='frame'?chosen():null;const n={...defaults,id:uid(),type,name:type==='text'?'Text':type==='frame'?'Frame':type==='image'?'Image':type==='shader'?'Shader':'Rectangle',x:parent?20:120+nodes().length*15%300,y:parent?20:150+nodes().length*15%200,w:type==='frame'?500:250,h:type==='text'?80:type==='frame'?360:180,color:type==='text'?'#25252e':type==='frame'?'#ffffff':'#97c3b1',text:type==='text'?'Your next idea':'',parentId:parent?.id||null,...extra};if(!n.parentId&&extra.x===undefined&&canvasApi){const view=canvasApi.placeInView(n.w,n.h),v=$('#canvas-wrap').getBoundingClientRect(),a=canvasApi.screenToWorld(v.left,v.top),b=canvasApi.screenToWorld(v.right,v.bottom);if(n.x<a.x||n.y<a.y||n.x+n.w>b.x||n.y+n.h>b.y){n.x=view.x;n.y=view.y}}nodes().push(n);selection=new Set([n.id]);render()}
